func GetDriverStoreGetDelay() time.Duration {
	defaultDuration := 10 * time.Millisecond

	e := os.Getenv("DRIVERSTORE_GET_DELAY")
	if e == "" {
		return defaultDuration
	}
	dur, err := time.ParseDuration(e)
	if err != nil {
		return defaultDuration
	}
	return dur
}

