                                    <Th isNumeric>Fare</Th>
                                </Tr>
                            </Thead>
                            <Tbody>
                                {rides.map(ride => (
                                    <Tr key={ride.id}>
                                        <Td whiteSpace='normal'>{ride.pickupLocationName}</Td>
                                        <Td whiteSpace='normal'>{ride.dropoffLocationName}</Td>
                                        <Td>{new Date(ride.requestTime).toLocaleString()}</Td>
                                        <Td>{ride.driverPlate || "—"}</Td>
                                        <Td isNumeric>{ride.fare === null ? "—" : formatFare(ride.fare)}</Td>
                                    </Tr>
                                ))}
                            </Tbody>
                        </Table>
                    </TableContainer>
                )}
            </CardBody>
        </Card>
    );
}
